"""Heat diffusion on the GPU.

Usage: python main.py INPUT_FILE

INPUT_FILE holds "<width> <height> <steps>" followed by height rows of width
integers. Each step replaces every cell with (4*self + left + right + up +
down) // 8, with out-of-grid neighbours clamped to the nearest edge cell. The
stencil runs as a compute shader; the final grid and its sum go to stdout.
"""

import sys

import numpy as np
import wgpu

WORKGROUP = 16

SHADER = """
struct Params {
    width: u32,
    height: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(%(wg)d, %(wg)d)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= params.width || y >= params.height) {
        return;
    }
    let w = params.width;
    let h = params.height;
    let xl = select(x - 1u, 0u, x == 0u);
    let xr = select(x + 1u, w - 1u, x + 1u >= w);
    let yu = select(y - 1u, 0u, y == 0u);
    let yd = select(y + 1u, h - 1u, y + 1u >= h);

    let c = src[y * w + x];
    let l = src[y * w + xl];
    let r = src[y * w + xr];
    let u = src[yu * w + x];
    let d = src[yd * w + x];
    dst[y * w + x] = (4u * c + l + r + u + d) / 8u;
}
""" % {"wg": WORKGROUP}


def read_input(path):
    with open(path, "r") as f:
        tokens = f.read().split()
    width, height, steps = (int(t) for t in tokens[:3])
    values = np.array(tokens[3 : 3 + width * height], dtype=np.uint32)
    return width, height, steps, values.reshape(height, width)


def get_device():
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    if adapter is None:
        adapter = wgpu.gpu.request_adapter_sync(force_fallback_adapter=True)
    return adapter.request_device_sync()


def diffuse(device, grid, steps):
    height, width = grid.shape
    usage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_DST | wgpu.BufferUsage.COPY_SRC
    size = grid.nbytes

    buffers = [
        device.create_buffer_with_data(data=grid.tobytes(), usage=usage),
        device.create_buffer(size=size, usage=usage),
    ]
    params = device.create_buffer_with_data(
        data=np.array([width, height], dtype=np.uint32).tobytes(),
        usage=wgpu.BufferUsage.UNIFORM,
    )

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )
    layout = pipeline.get_bind_group_layout(0)
    bind_groups = [
        device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": params, "offset": 0, "size": params.size}},
                {"binding": 1, "resource": {"buffer": buffers[i], "offset": 0, "size": size}},
                {"binding": 2, "resource": {"buffer": buffers[1 - i], "offset": 0, "size": size}},
            ],
        )
        for i in (0, 1)
    ]

    groups_x = (width + WORKGROUP - 1) // WORKGROUP
    groups_y = (height + WORKGROUP - 1) // WORKGROUP
    for step in range(steps):
        encoder = device.create_command_encoder()
        compute = encoder.begin_compute_pass()
        compute.set_pipeline(pipeline)
        compute.set_bind_group(0, bind_groups[step % 2])
        compute.dispatch_workgroups(groups_x, groups_y, 1)
        compute.end()
        device.queue.submit([encoder.finish()])

    final = buffers[steps % 2]
    data = device.queue.read_buffer(final, 0, size)
    return np.frombuffer(data, dtype=np.uint32).reshape(height, width)


def main():
    if len(sys.argv) < 2:
        sys.stderr.write("usage: python main.py INPUT_FILE\n")
        return 2

    width, height, steps, grid = read_input(sys.argv[1])
    if steps > 0:
        grid = diffuse(get_device(), grid, steps)

    out = sys.stdout
    for row in grid.tolist():
        out.write(" ".join(map(str, row)) + "\n")
    out.write(f"SUM {int(grid.sum(dtype=np.uint64))}\n")
    out.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main())

